import { readFileSync } from 'node:fs';
import { InMemorySpanExporter } from '@opentelemetry/sdk-trace';
import { afterEach, describe, expect, it, vi } from 'vitest';
import * as bindle from '../src/index.js';
import { RedactingSpanExporter } from '../src/export.js';
import { Redactor } from '../src/redact.js';
import { Poller, parseSettings } from '../src/remote.js';
import { sampled } from '../src/sampling.js';

// Shared with the Python SDK and Go ingest (generated by backend/internal/sdkconfig).
const vectors = JSON.parse(readFileSync(new URL('../../python/tests/sampling_vectors.json', import.meta.url), 'utf8')) as {
  trace_id: string;
  rate: number;
  sampled: boolean;
}[];

describe('sampling', () => {
  it('matches the shared vectors (same traces as Python and ingest)', () => {
    expect(vectors.length).toBeGreaterThan(50);
    for (const v of vectors) expect(sampled(v.trace_id, v.rate), `${v.trace_id}@${v.rate}`).toBe(v.sampled);
  });
});

describe('redaction', () => {
  const r = new Redactor();
  it('masks the built-in kinds', () => {
    expect(r.apply('mail bob@example.com now')).toBe('mail [REDACTED:EMAIL] now');
    expect(r.apply('key AKIAABCDEFGHIJKLMNOP')).toBe('key [REDACTED:SECRET]');
    expect(r.apply('Authorization: Bearer abcdefghijklmnopqrstuvwxyz123')).toBe('Authorization: [REDACTED:SECRET]');
    expect(r.apply('card 4111 1111 1111 1111')).toBe('card [REDACTED:CARD]');
    expect(r.apply('order 4111 1111 1111 1112')).not.toContain('REDACTED:CARD'); // fails Luhn
    expect(r.apply('ssn 123-45-6789')).toBe('ssn [REDACTED:SSN]');
  });
  it('adds extra patterns and skips invalid ones', () => {
    const bad: string[] = [];
    const x = new Redactor({ extra: { ORDER: 'ord_\\d+', BROKEN: '(' }, onInvalid: (n) => bad.push(n) });
    expect(x.apply('ord_42 for bob@example.com')).toBe('[REDACTED:ORDER] for [REDACTED:EMAIL]');
    expect(bad).toEqual(['BROKEN']);
    expect(new Redactor({ builtIn: false }).apply('bob@example.com')).toBe('bob@example.com');
  });
});

describe('remote settings', () => {
  it('parses and validates', () => {
    const s = parseSettings(JSON.stringify({ version: 3, sample_rate: 0.5, capture_content: false, redact_patterns: [{ name: 'ORDER', pattern: 'ord_\\d+' }, { name: 'bad name', pattern: 'x' }], poll_interval_seconds: 5 }));
    expect(s).toEqual({ version: 3, sampleRate: 0.5, captureContent: false, redactPatterns: { ORDER: 'ord_\\d+' }, pollIntervalSeconds: 30, limits: [], overBudget: [], stoppedRuns: [] });
    for (const bad of ['nope', '{"sample_rate":2,"capture_content":true}', '{"sample_rate":1}']) expect(parseSettings(bad)).toBeUndefined();
  });
  it('polls with the key, honors 304 and backs off on errors', async () => {
    const calls: Record<string, string>[] = [];
    let status = 200;
    const fake = (async (_url: string, init?: RequestInit) => {
      calls.push(init?.headers as Record<string, string>);
      if (status !== 200) return new Response(null, { status });
      return new Response(JSON.stringify({ version: 1, sample_rate: 0.25, capture_content: true }), { headers: { etag: '"v1"' } });
    }) as typeof fetch;
    const got: number[] = [];
    const p = new Poller('http://x/v1/config', 'bd_live_k', (s) => got.push(s.sampleRate), 'ua', fake);
    await p.pollOnce();
    status = 304;
    await p.pollOnce();
    expect(got).toEqual([0.25]);
    expect(calls[0]!.authorization).toBe('Bearer bd_live_k');
    expect(calls[1]!['if-none-match']).toBe('"v1"');
    status = 503;
    await p.pollOnce();
    await p.pollOnce();
    expect(p.nextDelaySeconds()).toBeGreaterThan(200); // 60 * 2^2, jittered
  });
});

describe('end to end', () => {
  let mem: InMemorySpanExporter;
  afterEach(async () => {
    await bindle.shutdown();
    vi.restoreAllMocks();
  });

  const start = (opts: bindle.InitOptions = {}) => {
    mem = new InMemorySpanExporter();
    const ok = bindle.init({ apiKey: 'bd_test_' + 'a'.repeat(40), endpoint: 'http://localhost:4318', agent: 'demo', remoteConfig: false, ...opts }, { exporter: () => mem });
    expect(ok).toBe(true);
  };
  const spans = async () => {
    await bindle.flush();
    return mem.getFinishedSpans();
  };

  it('is a no-op without a key and refuses plain http elsewhere', () => {
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => {});
    expect(bindle.init({ apiKey: '' })).toBe(false);
    expect(bindle.init({ apiKey: 'bd_live_x', endpoint: 'http://ingest.example.com' })).toBe(false);
    expect(warn).toHaveBeenCalledTimes(2);
  });

  it('traces tools, steps, decisions and sessions, redacted', async () => {
    start();
    const lookup = bindle.traceTool(async function lookup(email: string) {
      return { email, plan: 'pro' };
    });
    await bindle.withSession('sess-1', () =>
      bindle.step('plan', { type: 'agent' }, async () => {
        await lookup('bob@example.com');
        bindle.decision('route', ['crm', 'kb'], 'crm', 'needs account data');
        bindle.handoff('human', { reason: 'refund' });
      }),
    );
    const out = await spans();
    const byName = Object.fromEntries(out.map((s) => [s.name, s]));
    expect(Object.keys(byName).sort()).toEqual(['handoff -> human', 'lookup', 'plan', 'route']);
    const tool = byName.lookup!;
    expect(tool.attributes['bindle.step.type']).toBe('tool_call');
    expect(tool.attributes['bindle.tool.name']).toBe('lookup');
    expect(tool.attributes['input.value']).toBe('[REDACTED:EMAIL]');
    expect(tool.attributes['output.value']).toContain('[REDACTED:EMAIL]');
    expect(tool.attributes['bindle.session.id']).toBe('sess-1');
    expect(tool.parentSpanContext?.spanId).toBe(byName.plan!.spanContext().spanId);
    expect(byName.route!.attributes['bindle.decision.chosen']).toBe('crm');
    expect(tool.resource.attributes['bindle.agent.name']).toBe('demo');
  });

  it('records failures and rethrows', async () => {
    start();
    const boom = bindle.traceStep(() => {
      throw new Error('token sk-abcdefghijklmnopqrstuvwxyz leaked');
    }, { name: 'boom' });
    expect(() => boom()).toThrow('leaked');
    const [s] = await spans();
    expect(s!.status.code).toBe(2);
    expect(s!.status.message).toContain('[REDACTED:SECRET]');
  });

  it('remote settings are a ceiling', async () => {
    start({ sampleRate: 0.5 });
    bindle._applyRemote({ version: 2, sampleRate: 1, captureContent: false, redactPatterns: { ORDER: 'ord_\\d+' }, pollIntervalSeconds: 60, limits: [], overBudget: [] });
    expect(bindle._effective()).toEqual({ sampleRate: 0.5, captureContent: false, remoteVersion: 2 });
    bindle._applyRemote({ version: 3, sampleRate: 0, captureContent: true, redactPatterns: {}, pollIntervalSeconds: 60, limits: [], overBudget: [] });
    expect(bindle._effective().sampleRate).toBe(0);
  });

  it('drops content when capture is off', async () => {
    start({ captureContent: false, sampleRate: 1 });
    bindle.traceTool((q: string) => q.toUpperCase(), { name: 'shout' })('hello');
    const [s] = await spans();
    expect(s!.attributes['input.value']).toBeUndefined();
    expect(s!.attributes['bindle.tool.name']).toBe('shout');
  });
});

describe('exporter', () => {
  it('strips content keys and content events, and redacts the rest', () => {
    const mem = new InMemorySpanExporter();
    const ex = new RedactingSpanExporter(mem, new Redactor(), false);
    const span = {
      name: 'x', kind: 0, spanContext: () => ({ traceId: 'a'.repeat(32), spanId: 'b'.repeat(16), traceFlags: 1 }),
      startTime: [0, 0], endTime: [0, 1], duration: [0, 1], ended: true, status: { code: 0 },
      attributes: { 'input.value': 'secret prompt', 'gen_ai.input.messages': '[{"content":"secret"}]', 'gen_ai.tool.call.result': 'r', 'gen_ai.request.model': 'm', note: 'bob@example.com' },
      links: [], events: [{ name: 'gen_ai.content.prompt', attributes: {}, time: [0, 0] }, { name: 'gen_ai.user.message', attributes: { content: 'secret' }, time: [0, 0] }, { name: 'retry', attributes: { why: 'bob@example.com' }, time: [0, 0] }],
      resource: { attributes: {} }, instrumentationScope: { name: 't' }, droppedAttributesCount: 0, droppedEventsCount: 0, droppedLinksCount: 0,
    } as never;
    ex.export([span], () => {});
    const [out] = mem.getFinishedSpans();
    expect(out!.attributes).toEqual({ 'gen_ai.request.model': 'm', note: '[REDACTED:EMAIL]', 'bindle.content_dropped': 'sdk' });
    expect(out!.events.map((e) => e.name)).toEqual(['retry']);
    expect(out!.events[0]!.attributes!.why).toBe('[REDACTED:EMAIL]');
  });
});

describe('endpoint', () => {
  it('has no built-in default', () => {
    expect(bindle.resolveOptions({ apiKey: 'bd_test_x' }, {}).endpoint).toBe('');
    expect(bindle.resolveOptions({}, { BINDLE_ENDPOINT: 'https://ingest.example.com/' }).endpoint).toBe('https://ingest.example.com');
  });

  it('is a no-op without an endpoint, warning once', () => {
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => {});
    const saved = process.env.BINDLE_ENDPOINT;
    delete process.env.BINDLE_ENDPOINT;
    try {
      expect(bindle.init({ apiKey: 'bd_test_' + 'a'.repeat(40), remoteConfig: false })).toBe(false);
      expect(bindle.init({ apiKey: 'bd_test_' + 'a'.repeat(40), remoteConfig: false })).toBe(false);
      expect(bindle.spanProcessor({ apiKey: 'bd_test_' + 'a'.repeat(40) })).toBeUndefined();
      expect(warn.mock.calls.filter((c) => String(c[0]).includes('BINDLE_ENDPOINT'))).toHaveLength(1);
    } finally {
      if (saved !== undefined) process.env.BINDLE_ENDPOINT = saved;
      warn.mockRestore();
    }
  });
});
